/***
 * MARK: harnessPrefs
 * @description Pure helpers for the Harness Integration settings (System
 *   Settings › Harness tab). Preferences are keyed `{ [harnessId]: { enabled,
 *   autoDetect } }` so a newly registered harness simply appears with safe
 *   defaults and a removed one leaves a harmless orphan entry: unknown ids
 *   are ignored at render time, missing ids default to
 *   `{ enabled: true, autoDetect: true }`.
 *
 *   Manual-off always wins: `enabled: false` is never flipped back on by a
 *   probe — probes only feed the *availability* badge, never the prefs.
 * @example prefsForHarness({}, 'pi') => { enabled: true, autoDetect: true }
 * @example isHarnessEnabled({ pi: { enabled: false } }, 'pi') => false
 ***/

/***
 * MARK: HARNESS_PREFS_KEY
 * @description localStorage key backing the harness integration preferences
 *   (see `useHarnessPrefs`). Namespaced like every other `kainbain:` key.
 * @example HARNESS_PREFS_KEY // => 'kainbain:harnessPrefs'
 ***/
export const HARNESS_PREFS_KEY = 'kainbain:harnessPrefs';

/***
 * MARK: defaultHarnessPref
 * @description The safe default for a harness with no stored preference:
 *   visible and auto-detected. New registry entries appear without any
 *   migration step.
 * @example defaultHarnessPref() => { enabled: true, autoDetect: true }
 * @returns {{enabled: boolean, autoDetect: boolean}}
 ***/
export function defaultHarnessPref() {
  return { enabled: true, autoDetect: true };
}

/***
 * MARK: normalizeHarnessPrefs
 * @description Coerces a raw stored value into the prefs shape. Non-objects
 *   become `{}`, and entries without boolean-coercible flags fall back to the
 *   default — a corrupt or partial payload can never crash the settings tab.
 *   Unknown harness ids are kept when well-formed (harmless orphans); they
 *   are ignored at render time by `prefsForHarness` callers that only look up
 *   registered ids.
 * @example normalizeHarnessPrefs(null) => {}
 * @example normalizeHarnessPrefs({ pi: { enabled: false } }) => { pi: { enabled: false, autoDetect: true } }
 * @param {unknown} raw - The raw stored value.
 * @returns {Object} Normalized `{ [id]: { enabled, autoDetect } }`.
 ***/
export function normalizeHarnessPrefs(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
  const prefs = {};
  for (const [id, entry] of Object.entries(raw)) {
    if (!id || !entry || typeof entry !== 'object' || Array.isArray(entry)) continue;
    prefs[id] = {
      enabled: entry.enabled === undefined ? true : Boolean(entry.enabled),
      autoDetect: entry.autoDetect === undefined ? true : Boolean(entry.autoDetect),
    };
  }
  return prefs;
}

/***
 * MARK: prefsForHarness
 * @description Reads one harness's preference, defaulting to
 *   `{ enabled: true, autoDetect: true }` when the id has no stored entry
 *   (older payloads, brand-new harnesses).
 * @example prefsForHarness({}, 'antigravity') => { enabled: true, autoDetect: true }
 * @param {Object} [prefs] - Normalized prefs map.
 * @param {string} id - Harness id.
 * @returns {{enabled: boolean, autoDetect: boolean}}
 ***/
export function prefsForHarness(prefs, id) {
  const entry = prefs?.[id];
  if (!entry || typeof entry !== 'object') return defaultHarnessPref();
  return {
    enabled: entry.enabled === undefined ? true : Boolean(entry.enabled),
    autoDetect: entry.autoDetect === undefined ? true : Boolean(entry.autoDetect),
  };
}

/***
 * MARK: isHarnessEnabled
 * @description Reports whether a harness is enabled (defaults to true when
 *   the prefs carry no entry for the id).
 * @example isHarnessEnabled({ pi: { enabled: false } }, 'pi') => false
 * @param {Object} [prefs] - Normalized prefs map.
 * @param {string} id - Harness id.
 * @returns {boolean}
 ***/
export function isHarnessEnabled(prefs, id) {
  return prefsForHarness(prefs, id).enabled;
}

/***
 * MARK: isHarnessAutoDetect
 * @description Reports whether auto-detection is on for a harness (defaults
 *   to true when the prefs carry no entry for the id).
 * @example isHarnessAutoDetect({}, 'pi') => true
 * @param {Object} [prefs] - Normalized prefs map.
 * @param {string} id - Harness id.
 * @returns {boolean}
 ***/
export function isHarnessAutoDetect(prefs, id) {
  return prefsForHarness(prefs, id).autoDetect;
}

/***
 * MARK: withHarnessPref
 * @description Returns a new prefs map with one harness's flags patched
 *   (never mutates the input). Unknown ids are stored verbatim — they stay
 *   invisible until a harness registers under that id.
 * @example withHarnessPref({}, 'pi', { enabled: false }) => { pi: { enabled: false, autoDetect: true } }
 * @param {Object} [prefs] - Normalized prefs map.
 * @param {string} id - Harness id.
 * @param {Object} [patch] - Partial flags (`{ enabled }`, `{ autoDetect }`).
 * @returns {Object} New prefs map.
 ***/
export function withHarnessPref(prefs, id, patch = {}) {
  const current = prefsForHarness(prefs, id);
  return { ...(prefs || {}), [id]: { ...current, ...patch } };
}

/***
 * MARK: enabledHarnesses
 * @description Filters a harness list down to the enabled entries. Disabled
 *   harnesses are NOT hidden by this helper's callers in pickers — they
 *   render disabled-with-reason (the `ModelSelector` contract) — but the
 *   *default-harness* selector only offers enabled ones.
 * @example enabledHarnesses([{ id: 'pi' }, { id: 'agy' }], { agy: { enabled: false } }) => [{ id: 'pi' }]
 * @param {Array<Object>} harnesses - Harness entries (`{ id, … }`).
 * @param {Object} [prefs] - Normalized prefs map.
 * @returns {Array<Object>} Enabled entries in list order.
 ***/
export function enabledHarnesses(harnesses, prefs) {
  return (Array.isArray(harnesses) ? harnesses : []).filter((h) =>
    isHarnessEnabled(prefs, h?.id),
  );
}

/***
 * MARK: harnessDisabledReason
 * @description The disabled-with-reason string for the `ModelSelector`
 *   `isHarnessDisabled` contract: null when the harness stays selectable, a
 *   human reason when the user disabled it in System Settings › Harness.
 *   Never hides — the caller renders the option disabled with this text.
 * @example harnessDisabledReason({ pi: { enabled: false } }, { id: 'pi', label: 'pi' }) => 'Disabled in System Settings › Harness'
 * @example harnessDisabledReason({}, { id: 'pi' }) => null
 * @param {Object} [prefs] - Normalized prefs map.
 * @param {Object} harness - Harness entry (`{ id, label? }`).
 * @returns {string|null} Reason string, or null when selectable.
 ***/
export function harnessDisabledReason(prefs, harness) {
  if (!harness || isHarnessEnabled(prefs, harness.id)) return null;
  return 'Disabled in System Settings › Harness';
}

/***
 * MARK: deriveAvailability
 * @description Derives one harness's honest availability from a models probe
 *   (`GET /harnesses/:id/models`): `'detected'` (usable signal), `'unavailable'`
 *   (a catalogue harness that discovered nothing), or `'unknown'` (not probed
 *   yet, probe failed, or the harness manages its own model so an empty
 *   catalogue says nothing — e.g. `custom`, `muse`). Manual-off never reaches
 *   this function: the caller renders `Disabled` first so a probe can never
 *   override an explicit off.
 * @example deriveAvailability({ id: 'pi', modelSelection: 'list' }, { models: [{ id: 'm' }] }) => 'detected'
 * @example deriveAvailability({ id: 'custom', modelSelection: 'none' }, { models: [] }) => 'unknown'
 * @param {Object} harness - Harness entry (`{ id, modelSelection? }`).
 * @param {Object|null} probe - Probe result (`{ models }`), `{ error }` on failure, or null when not probed.
 * @returns {string} 'detected' | 'unavailable' | 'unknown'.
 ***/
export function deriveAvailability(harness, probe) {
  if (!probe || probe.error || !Array.isArray(probe.models)) return 'unknown';
  if ((harness?.modelSelection || 'list') === 'none') return 'unknown';
  return probe.models.length > 0 ? 'detected' : 'unavailable';
}

/***
 * MARK: availabilityBadge
 * @description Presentation for one harness row's status: the honest probe
 *   outcome, with manual-off taking precedence over everything (a disabled
 *   harness shows `Disabled`, never its last probe result).
 * @example availabilityBadge({ enabled: false }, 'detected') => { text: 'Disabled', tone: 'muted' }
 * @param {{enabled: boolean, autoDetect: boolean}} pref - The harness's pref entry.
 * @param {string} availability - 'detected' | 'unavailable' | 'unknown'.
 * @returns {{text: string, tone: string}} Label + tone ('good' | 'bad' | 'muted').
 ***/
export function availabilityBadge(pref, availability) {
  if (pref && pref.enabled === false) return { text: 'Disabled', tone: 'muted' };
  if (pref && pref.autoDetect === false && availability === 'unknown') {
    return { text: 'Auto-detect off', tone: 'muted' };
  }
  if (availability === 'detected') return { text: 'Detected', tone: 'good' };
  if (availability === 'unavailable') return { text: 'Unavailable', tone: 'bad' };
  return { text: 'Unknown', tone: 'muted' };
}

/***
 * MARK: availabilityFromEntry
 * @description Derives one harness's availability from a backend catalogue
 *   entry's discovery projection (`available: true | false | null`): the
 *   badge input for pickers that render straight from `/compute/models`
 *   (no on-demand probe). Entries from older backends carry no `available`
 *   field at all — those read as null (badge-free, never mislead) rather
 *   than 'unknown'.
 * @example availabilityFromEntry({ id: 'pi', available: true }) => 'detected'
 * @example availabilityFromEntry({ id: 'pi', available: false }) => 'unavailable'
 * @example availabilityFromEntry({ id: 'pi', available: null }) => 'unknown'
 * @example availabilityFromEntry({ id: 'pi' }) => null
 * @param {Object} entry - Harness view entry (`{ available? }`).
 * @returns {string|null} 'detected' | 'unavailable' | 'unknown' | null (predates availability).
 ***/
export function availabilityFromEntry(entry) {
  if (!entry || entry.available === undefined) return null;
  if (entry.available === true) return 'detected';
  if (entry.available === false) return 'unavailable';
  return 'unknown';
}

/***
 * MARK: availabilityToneClass
 * @description Tailwind classes for one availability badge tone. Shared by
 *   the System Settings harness list and the model pickers so tones can
 *   never drift apart between surfaces. Colors follow the DiffView badge
 *   recipe exactly (dark 900-step translucent fill + 300-step text): 10px
 *   bold badge text is WCAG normal text and the settings-view axe gate
 *   enforces AAA enhanced contrast (1.4.6, 7:1) — the lighter 500/15 fill
 *   only reaches ~5.8:1 with 300-step text, while the 900/30 fill clears
 *   7:1 on the same dark backdrops.
 * @example availabilityToneClass('good') => 'bg-green-…'
 * @param {string} tone - 'good' | 'bad' | 'muted'.
 * @returns {string} Class names for the badge pill.
 ***/
export function availabilityToneClass(tone) {
  if (tone === 'good') {
    return 'bg-green-900/30 text-green-300 border-green-700/50';
  }
  if (tone === 'bad') {
    return 'bg-red-900/30 text-red-300 border-red-700/60';
  }
  return 'bg-surface-container-high text-text-muted border-border-standard';
}

import React, {
  createContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  useContext,
} from 'react';

import { useLocation, useNavigate } from 'react-router';
import { api } from '../services/api';
import { logger } from '../services/logger';
import { useWebSocket } from './useWebSocket';
import { useTasks } from './useTasks';
import { useWorkflow } from './useWorkflow';
import { useProjects } from './useProjects';
import { useSkills } from './useSkills';
import { useUiPreferences } from './useUiPreferences';
import { useHarnessPrefs } from '../hooks/useHarnessPrefs';
import { useNotifications } from './useNotifications';
import { useViewNavigation } from './useViewNavigation';
import { useSelectedTask } from './useSelectedTask';
import { useEngineStatus } from './useEngineStatus';
import { useTaskSubmission } from './useTaskSubmission';
import { useBoardSync } from './useBoardSync';
import { useStageNavigation } from './useStageNavigation';
import { useAccentTheme } from './useAccentTheme';
import { usePendingTaskSave } from './usePendingTaskSave';

/**
 * MARK: KainBainContext
 * @description Centralized state + actions for the KainBain orchestrator.
 * The provider composes small domain hooks so no single file owns all of the
 * app's state. Domain logic lives in: useViewNavigation (router-backed views),
 * useSelectedTask (inspector snapshot + hydration), useEngineStatus (health +
 * compute), useTaskSubmission (goal dispatch + workflow start), useBoardSync
 * (live-sync refs + polling), useStageNavigation (focus + skip), useAccentTheme
 * (per-project tint), usePendingTaskSave (editor flush) — plus the long-lived
 * useWebSocket/useTasks/useWorkflow/useProjects/useSkills/useNotifications
 * collection hooks. This module only wires them and assembles `value`.
 */

const KainBainContext = createContext(null);

export { KainBainContext };

export function KainBainProvider({ children }) {
  const notificationsHook = useNotifications();
  const {
    notifications,
    addNotification,
    dismissNotification,
    clearAllNotifications,
    notifySuccess,
    notifyInfo,
    notifyWarning,
    notifyError,
  } = notificationsHook;

  // Keeps the live board sync handlers pointed at the latest pieces of state
  // without forcing re-creation of the (early-constructed) WebSocket hook.
  const activeProjectIdRef = useRef(null);
  const taskSyncHandlerRef = useRef(null); // (projectId) => void
  const updateProjectInStateRef = useRef(null); // (project) => void
  // Latest engine snapshot for the cross-project owner check below, plus the
  // engine-state setter so an owner update can refresh the bar's
  // project-independent snapshot without rebuilding the socket hook.
  const engineStateRef = useRef(null);
  const setEngineStateRef = useRef(null);
  // Latest REVIEW_UPDATED WS payload. The TaskReviewPage subscribes to this so
  // comment edits elsewhere (another tab) land without a manual refresh.
  const [lastReviewEvent, setLastReviewEvent] = useState(null);
  // Latest CHAT_PROGRESS WS payload. The ChatTurnProvider subscribes to this
  // so the working card scrolls live model output while a turn runs.
  const [lastChatProgress, setLastChatProgress] = useState(null);
  // UI-level chrome state (not owned by a single domain hook).
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSystemGuideOpen, setIsSystemGuideOpen] = useState(false);

  const ws = useWebSocket({
    onNotification: addNotification,
    // Live board sync: a task changed / was deleted elsewhere (drag in another
    // tab, agent stage advance, create). Route it to a coalesced task refresh
    // so the board reflects the new position without a page refresh.
    onTaskUpdated: (task) => {
      // Single-pipeline bar: the engine owner lives outside the selected
      // project after a switch, and its frames would be dropped below. Keep
      // the project-independent snapshot (`engineState.activeTask`) fresh so
      // the bar tracks the owner's live title/status while the board below
      // still filters per project.
      if (
        task?.id != null &&
        engineStateRef.current?.activeTaskId != null &&
        String(task.id) === String(engineStateRef.current.activeTaskId)
      ) {
        setEngineStateRef.current?.((prev) =>
          prev && String(prev.activeTaskId) === String(task.id)
            ? { ...prev, activeTask: task }
            : prev,
        );
      }
      const pid = activeProjectIdRef.current;
      if (!pid) return;
      // The socket is project-bound but the backend broadcasts globally; ignore
      // updates for a different project so no stray cross-project card appears.
      if (task && task.projectId && String(task.projectId) !== String(pid)) return;
      // Merge the live payload straight onto the board so a task created or
      // moved elsewhere (another tab, the agent itself) appears/updates
      // instantly, then still run the coalesced full fetch below to reconcile
      // anything the snapshot misses.
      tasks.upsertTask?.(task);
      taskSyncHandlerRef.current?.(pid);
    },
    onTaskDeleted: ({ projectId } = {}) => {
      const pid = activeProjectIdRef.current;
      if (!pid) return;
      if (projectId && String(projectId) !== String(pid)) return;
      taskSyncHandlerRef.current?.(pid);
    },
    // PR review: comment mutations from anywhere (another tab, the review
    // page itself) surface here so the open review view can merge them live.
    onReviewUpdated: (event) => {
      setLastReviewEvent({ ...event, _seq: Date.now() });
    },
    // Chat progress: streamed tails for the in-flight turn (matched by
    // turnId in the ChatTurnProvider; other tabs' turns are ignored there).
    onChatProgress: (event) => {
      setLastChatProgress({ ...event, _seq: Date.now() });
    },
    // App link: a "Go to App" record changed elsewhere (script PATCH, agent
    // skill, health probe) — merge it so the link appears without a refresh.
    // The project list is global (not active-project scoped), so every
    // update merges; unknown ids are a no-op in updateProjectInState.
    onProjectUpdated: (project) => {
      if (project?.id) updateProjectInStateRef.current?.(project);
    },
    // After a reconnect (or initial connect), catch up any board-position
    // changes that occurred while disconnected or in a throttled background tab.
    onReconnect: (projectId) => taskSyncHandlerRef.current?.(projectId),
  });
  const tasks = useTasks({ onNotification: addNotification });
  const workflow = useWorkflow({ onNotification: addNotification });

  // Destructure the stable hook functions so callbacks can list precise deps
  // instead of depending on the (per-render) hook objects.
  const { connectWebSocket, setMessages, setToolCalls, isAgentRunning } = ws;
  const { fetchTasks } = tasks;
  const { fetchWorkflow, currentStageId } = workflow;

  // The engine owns one global queue, so compute start/stop resolves its
  // target project from the engine owner (ws.engineState), not the selection.
  const engine = useEngineStatus({
    notifySuccess,
    notifyInfo,
    notifyError,
    engineState: ws.engineState,
  });

  const submission = useTaskSubmission({
    isAgentRunning,
    currentStageId,
    activeWorkflowId: workflow.activeWorkflowId,
    setMessages,
    setToolCalls,
    fetchTasks,
    fetchWorkflowList: workflow.fetchWorkflows,
    notifySuccess,
    notifyInfo,
    notifyError,
  });

  // ---- Load all data for a project after activation ----
  const loadProjectData = useCallback(
    async (projectId) => {
      connectWebSocket(projectId);
      await Promise.all([engine.fetchStatus(), fetchTasks(projectId), fetchWorkflow(projectId)]);
    },
    [connectWebSocket, engine, fetchTasks, fetchWorkflow],
  );

  const projects = useProjects({
    onSelectProject: loadProjectData,
    onNotification: addNotification,
  });

  // Keep the live app-link sync pointed at the latest project merger without
  // forcing re-creation of the (early-constructed) WebSocket hook.
  useEffect(() => {
    updateProjectInStateRef.current = projects.updateProjectInState;
  }, [projects.updateProjectInState]);

  // Keep the cross-project engine-owner check pointed at the latest engine
  // snapshot (and its setter) without rebuilding the socket hook.
  useEffect(() => {
    engineStateRef.current = ws.engineState;
    setEngineStateRef.current = ws.setEngineState;
  }, [ws.engineState, ws.setEngineState]);

  // Stage-skills library (lazily fetched when the workflow editor opens).
  // Declared after `projects` so the active-project scope is available.
  const skills = useSkills({ activeProjectId: projects?.activeProjectId });

  const selection = useSelectedTask({
    tasksList: tasks.tasks,
    activeProjectId: projects?.activeProjectId,
  });

  const nav = useViewNavigation({
    tasksList: tasks.tasks,
    selectedSnapshot: selection.selectedTaskSnapshot,
    setSelectedSnapshot: selection.setSelectedTaskSnapshot,
  });

  useBoardSync({
    activeProjectIdRef,
    taskSyncHandlerRef,
    activeProjectId: projects?.activeProjectId,
    tasks,
  });

  const stageNav = useStageNavigation({ tasks, workflow, engineState: ws.engineState });

  const pendingSave = usePendingTaskSave();

  useAccentTheme({ projects });

  const uiPrefs = useUiPreferences();
  // Harness integration prefs (System Settings › Harness): enabled +
  // autoDetect per harness id, persisted to localStorage — the single
  // instance shared by the settings panel and every ModelSelector's
  // isHarnessDisabled predicate, so toggles apply app-wide without remounts.
  const harnessPrefsState = useHarnessPrefs();

  // ---- Initialization ----
  useEffect(() => {
    const init = async () => {
      await projects.fetchProjects();
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // When the active project is known, load its data and connect.
  useEffect(() => {
    if (!projects.activeProjectId) return;
    connectWebSocket(projects.activeProjectId);
    void (async () => {
      await Promise.all([
        engine.fetchStatus(),
        fetchTasks(projects.activeProjectId),
        workflow.fetchWorkflows(projects.activeProjectId),
        fetchWorkflow(projects.activeProjectId),
      ]);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects.activeProjectId]);

  // Keep the inspector's task in sync with the freshest board snapshot done via derivation above.

  const restoreSession = useCallback(
    async (projectId) => {
      if (!projectId) return;
      try {
        const data = await api.restoreSession(projectId);
        if (data?.messages) {
          setMessages(data.messages);
        }
        await Promise.all([fetchTasks(projectId), fetchWorkflow(projectId)]);
        notifySuccess('Session state restored from disk', 'Session Restored');
        return data;
      } catch (e) {
        logger.error('Failed to restore session', e);
        notifyError('Failed to restore session from disk', 'Restore Error');
      }
    },
    [fetchTasks, fetchWorkflow, setMessages, notifySuccess, notifyError],
  );

  const value = {
    // top-level state
    view: nav.view,
    setView: nav.setView,
    // Router bridge internals (consumed only by KainBainRouteBridge).
    __registerRouter: nav.registerRouter,
    __syncRouteLocation: nav.syncRouteLocation,
    computeRunning: engine.computeRunning,
    tasks: tasks.tasks,
    tasksLoading: tasks.isLoading,
    tasksError: tasks.tasksError,
    retryTasks: tasks.fetchTasks,
    newTaskGoal: submission.newTaskGoal,
    setNewTaskGoal: submission.setNewTaskGoal,
    workflowId: submission.workflowId,
    setWorkflowId: submission.setWorkflowId,
    isFollowUp: submission.isFollowUp,
    setIsFollowUp: submission.setIsFollowUp,
    selectedTask: selection.selectedTask,
    setSelectedTask: selection.setSelectedTask,
    // Latest REVIEW_UPDATED WS payload for live comment merging in the review view
    lastReviewEvent,
    // Latest CHAT_PROGRESS WS payload for the working card's live output
    lastChatProgress,
    // Pending task-editor save flush (checkpoint approve/reject gating)
    setPendingTaskSaveFlush: pendingSave.setPendingTaskSaveFlush,
    hasPendingTaskSaveFlush: pendingSave.hasPendingTaskSaveFlush,
    flushPendingTaskSave: pendingSave.flushPendingTaskSave,
    isSettingsOpen,
    setIsSettingsOpen,
    previewPrompt: submission.previewPrompt,
    setPreviewPrompt: submission.setPreviewPrompt,
    fetchHealth: engine.fetchHealth,
    isHealthRefreshing: engine.isHealthRefreshing,
    healthState: engine.healthState,
    // domain hooks
    projects: projects.projects,
    visibleProjects: projects.visibleProjects,
    activeProjectId: projects.activeProjectId,
    activeProject: projects.activeProject,
    isProjectDropdownOpen: projects.isProjectDropdownOpen,
    setIsProjectDropdownOpen: projects.setIsProjectDropdownOpen,
    hiddenProjectIds: projects.hiddenProjectIds,
    toggleHideProject: projects.toggleHideProject,
    showArchived: projects.showArchived,
    setShowArchived: projects.setShowArchived,
    stages: workflow.stages,
    workflowLoading: workflow.isLoading,
    workflowSwitching: workflow.isSwitching,
    currentStageId: workflow.currentStageId,
    activeWorkflowId: workflow.activeWorkflowId,
    projectWorkflows: workflow.workflows,
    workflows: workflow.workflows,
    workflowRuns: workflow.workflowRuns,
    focusedStageId: stageNav.focusedStageId,
    setFocusedStageId: stageNav.setFocusedStageId,
    feedbackTask: tasks.feedbackTask,
    messages: ws.messages,
    toolCalls: ws.toolCalls,
    isAgentRunning: ws.isAgentRunning,
    processLogs: ws.processLogs,
    clearLogs: ws.clearLogs,
    addProcessLog: ws.addProcessLog,
    engineState: ws.engineState,
    connectionStatus: ws.connectionStatus,
    // notifications state & actions
    notifications,
    addNotification,
    dismissNotification,
