                setDirConfirm(null);
                // Typing clears this field's error: the message describes the
                // last save attempt, and keeping it while the text changes
                // reads as if the new text already failed.
                setDirErrors((prev) => {
                  const next = { ...prev };

                  delete next[`${selected.runnerId}:worktreeDir`];
